<template><section class="page"><header><div><h1 class="page-title">意见反馈管理</h1><p class="page-description">处理并回复 App 用户反馈；该模块不设置启用或停用。</p></div><el-tag type="warning">待处理 {{pending}}</el-tag></header><div class="filters"><el-input v-model="keyword" clearable placeholder="搜索反馈内容或 ID"/><el-select v-model="status"><el-option label="全部状态" value="ALL"/><el-option v-for="s in states" :key="s" :label="s" :value="s"/></el-select></div><el-table :data="visible"><el-table-column prop="id" label="反馈 ID" width="100"/><el-table-column prop="content" label="反馈内容" min-width="320"/><el-table-column prop="type" label="类型" width="100"/><el-table-column prop="platform" label="平台" width="100"/><el-table-column prop="user" label="用户" width="130"/><el-table-column prop="time" label="反馈时间" width="170"/><el-table-column label="状态" width="100"><template slot-scope="s"><el-tag :type="s.row.status==='待处理'?'warning':'success'">{{s.row.status}}</el-tag></template></el-table-column><el-table-column label="操作" width="120"><template slot-scope="s"><el-button type="text" @click="open(s.row)">查看与回复</el-button></template></el-table-column></el-table><el-dialog title="处理用户反馈" :visible.sync="dialog" width="620px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="反馈内容">{{current.content}}</el-descriptions-item><el-descriptions-item label="用户">{{current.user}}</el-descriptions-item><el-descriptions-item label="平台">{{current.platform}}</el-descriptions-item></el-descriptions><el-form label-width="90px" class="reply"><el-form-item label="处理状态"><el-select v-model="draftStatus"><el-option v-for="s in states" :key="s" :label="s" :value="s"/></el-select></el-form-item><el-form-item label="回复用户"><el-input v-model="reply" type="textarea" :rows="4" placeholder="输入回复内容"/></el-form-item></el-form><span slot="footer"><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存处理结果</el-button></span></el-dialog></section></template>
<script>export default{data:()=>({keyword:'',status:'ALL',dialog:false,current:null,draftStatus:'待处理',reply:'',states:['待处理','处理中','已回复','已关闭'],rows:[{id:8052,type:'试题',platform:'Android',user:'用户 6***8',content:'前几天做的题记录没了，笔记也没有找到。',time:'2026-09-02 21:35',status:'待处理',reply:''},{id:8051,type:'试题',platform:'Android',user:'用户 7***0',content:'模拟考试估分结果无法正常显示。',time:'2026-09-02 14:56',status:'待处理',reply:''},{id:8050,type:'功能',platform:'iOS',user:'用户 3***0',content:'试卷页面没有显示标题。',time:'2026-09-02 14:04',status:'处理中',reply:''}]}),computed:{pending(){return this.rows.filter(x=>x.status==='待处理').length},visible(){const q=this.keyword.toLowerCase();return this.rows.filter(x=>(this.status==='ALL'||x.status===this.status)&&(!q||(x.content+x.id).toLowerCase().includes(q))) }},methods:{open(x){this.current=x;this.draftStatus=x.status;this.reply=x.reply;this.dialog=true},save(){if(this.draftStatus==='已回复'&&!this.reply.trim())return this.$message.warning('状态为“已回复”时必须填写回复内容');Object.assign(this.current,{status:this.draftStatus,reply:this.reply});this.dialog=false;this.$message.success('处理结果已保存')}}}</script>
<style scoped>.page{max-width:1440px;margin:auto}.page>header{display:flex;justify-content:space-between;align-items:flex-end}.filters{display:flex;gap:12px;margin:24px 0}.filters .el-input{width:360px}.reply{margin-top:20px}</style>
